CodeInjections.CodeInjection:
float3 cargoScale;
float3 cargoOffset;
float3 cargoRow0;
float3 cargoRow1;
float3 cargoRow2;

float3 cargoToFrame(float3 v, ObjectParameters& object)
{
    return float3(dot(object.cargoRow0, v), dot(object.cargoRow1, v), dot(object.cargoRow2, v));
}
float3 cargoFromFrame(float3 q, ObjectParameters& object)
{
    return q.x * object.cargoRow0 + q.y * object.cargoRow1 + q.z * object.cargoRow2;
}
float3 cargoFitPoint(float3 p, ObjectParameters& object)
{
    return cargoFromFrame(cargoToFrame(p, object) * object.cargoScale, object) + object.cargoOffset;
}

float3 position = cargoFitPoint(In.position.xyz, object);
#if defined(SKINNING)
    return skinPoint(position, In, instance, object);
#else
    return position;
#endif

float3 position = cargoFitPoint(In.position.xyz, object);
#if defined(SKINNING)
    return skinPrevPoint(position, In, instance, object);
#else
    return position;
#endif

float3 normal = normalize(cargoFromFrame(cargoToFrame(In.normal.xyz, object) / object.cargoScale, object));
#if defined(SKINNING)
    return skinVector(normal, In, instance, object);
#else
    return normal;
#endif

float3 tangent = normalize(cargoFromFrame(cargoToFrame(In.tangent.xyz, object) * object.cargoScale, object));
#if defined(SKINNING)
    return skinVector(tangent, In, instance, object);
#else
    return tangent;
#endif
